<script setup lang="ts">import{ref,onMounted,watch,computed}from 'vue';import{lab,load}from '../stores/research';import{canEdit}from '../stores/auth';import*as studies from '../api/studies';import*as strataApi from '../api/strata';import*as countsApi from '../api/counts';import type{Stratum,Count,TableRow}from '../types/domain';import{useTask}from '../hooks/useTask';import StudySelect from '../components/StudySelect.vue';import StratumTable from '../components/StratumTable.vue';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const selected=ref(0),strata=ref<Stratum[]>([]),counts=ref<TableRow[]>([]),stratum=ref(0),description=ref(''),notice=ref(''),studyCode=ref('CN-NEW'),studyName=ref('新封装分层试验'),code=ref('CN-NEW-1'),name=ref('预设湿度层'),a=ref(0),b=ref(0),c=ref(0),d=ref(0),source=ref('CN_独立试片.csv'),{error,execute}=useTask();const rows=computed(()=>counts.value);function pickCount(){const t=counts.value.find(t=>t.stratum_id===stratum.value);a.value=t?.a||0;b.value=t?.b||0;c.value=t?.c||0;d.value=t?.d||0;source.value=t?.source||'CN_独立试片.csv'}async function refresh(){const id=selected.value;const[s,t]=await Promise.all([strataApi.list(id),countsApi.list(id)]);if(selected.value!==id)return;strata.value=s;counts.value=t;description.value=lab.studies.find(s=>s.id===id)?.description||'';stratum.value=s.some(s=>s.id===stratum.value)?stratum.value:s[0]?.id||0;pickCount()}watch(selected,()=>execute(refresh));watch(stratum,pickCount);onMounted(()=>execute(async()=>{await load();selected.value=lab.studies[0]?.id||0}));function saveCounts(){execute(async()=>{await countsApi.save(stratum.value,{a:a.value,b:b.value,c:c.value,d:d.value,source:source.value});await refresh();notice.value='四格计数已保存；已有冻结研究不会改变'})}function annotate(){execute(async()=>{await studies.patch(selected.value,description.value);await load();notice.value='研究批注已保存'})}function createStudy(){execute(async()=>{const s=await studies.create({code:studyCode.value,name:studyName.value,period:'2026-11',description:'预先分层的独立封装试片'});await load();selected.value=s.id;notice.value='新底稿已建立，请添加预设层'})}function addStratum(){execute(async()=>{const s=await strataApi.create({study_id:selected.value,code:code.value,name:name.value,description:'预设分层，先填写独立试片计数'});await refresh();stratum.value=s.id;pickCount();notice.value='分层已建立，请填完整四格'})}</script><template><PageHeading index="02" title="四格计数，先认清行列。" text="上游匿名试片汇总；研究时冻结全部预设层，之后修改不会覆盖历史快照。"/><ErrorNotice :message="error" @retry="execute(refresh)"/><p v-if="notice" role="status" class="success">{{notice}}</p><StudySelect :studies="lab.studies" v-model="selected"/><div class="source-key"><div><b>A方法</b><span>a = 成功 / b = 失败</span></div><div><b>B方法</b><span>c = 成功 / d = 失败</span></div><p>OR = ad/bc；成功率比较与OR的量纲不同。</p></div><StratumTable :rows="rows"/><div v-if="canEdit" class="source-edit-grid"><form @submit.prevent="saveCounts"><h2>修订一层计数</h2><label>预设层<select v-model="stratum" aria-label="编辑分层"><option v-for="s in strata" :value="s.id" :key="s.id">{{s.code}} {{s.name}}</option></select></label><div class="four-counts"><label>A成功 a<input v-model.number="a" type="number" min="0" max="500" step="1" required/></label><label>A失败 b<input v-model.number="b" type="number" min="0" max="500" step="1" required/></label><label>B成功 c<input v-model.number="c" type="number" min="0" max="500" step="1" required/></label><label>B失败 d<input v-model.number="d" type="number" min="0" max="500" step="1" required/></label></div><label>来源文件<input v-model="source" maxlength="160"/></label><button class="primary" :disabled="!stratum">保存四格计数 →</button></form><form @submit.prevent="annotate"><h2>底稿批注</h2><label>研究批注<textarea v-model="description" rows="7" maxlength="1600"/></label><button class="outline">保存批注</button></form></div><div v-if="canEdit" class="setup-folds"><details><summary>新增预设层</summary><form @submit.prevent="addStratum"><label>层编号<input v-model="code" pattern="[A-Z0-9-]+" required/></label><label>层名称<input v-model="name" required/></label><button class="outline">建立分层</button></form></details><details><summary>登记另一份试验底稿</summary><form @submit.prevent="createStudy"><label>研究编号<input v-model="studyCode" pattern="[A-Z0-9-]+" required/></label><label>研究名称<input v-model="studyName" required/></label><button class="outline">登记底稿</button></form></details></div></template>
